# python
# Robust detection + fallback to sliding window + segmentation with error handling

# Try standard detection for "ball"
try:
    image_1_ball_detection, image_1_ball_boxes = detection(image_1, ["ball"])
    if image_1_ball_detection is not None:
        print("Detection succeeded for 'ball'.")
        display(image_1_ball_detection.annotated_image)
        print("Detected ball boxes (normalized [x,y,w,h]):", image_1_ball_boxes)
    else:
        raise RuntimeError("detection returned None for annotated image.")
except Exception as e:
    print("Standard detection failed with error:", repr(e))
    print("Falling back to sliding_window_detection for 'ball'...")
    try:
        possible_patches, possible_boxes = sliding_window_detection(image_1, ["ball"])
        if possible_patches:
            print(f"sliding_window_detection returned {len(possible_patches)} patch(es). Displaying them:")
            for i, patch in enumerate(possible_patches, start=1):
                print(f"Patch {i}:")
                display(patch.annotated_image)
            print("Detected boxes within patches (coordinates relative to each patch):", possible_boxes)
        else:
            print("sliding_window_detection did not return any patches.")
    except Exception as e2:
        print("sliding_window_detection also failed with error:", repr(e2))

# Try segmentation and marking to get regions for further reasoning
try:
    image_1_segmented, image_1_seg_boxes = segment_and_mark(image_1)
    if image_1_segmented is not None:
        print("Segmentation succeeded. Displaying segmented/marked image:")
        display(image_1_segmented.annotated_image)
        print(f"Number of segmented regions: {len(image_1_seg_boxes)}")
        for idx, bbox in enumerate(image_1_seg_boxes, start=1):
            print(f"Segment {idx}: {bbox}")
    else:
        raise RuntimeError("segment_and_mark returned None for annotated image.")
except Exception as e:
    print("Segmentation failed with error:", repr(e))

print("Finished diagnostic attempts. Use the displayed outputs (if any) to continue the analysis.")
